pub(crate) fn update_available_label(language: UiLanguage, version: Option<&str>) -> String {
    let base = match language {
        UiLanguage::ChineseSimplified => "新版本",
        UiLanguage::ChineseTraditional => "新版本",
        UiLanguage::Japanese => "更新",
        UiLanguage::Korean => "업데이트",
        UiLanguage::French => "Màj",
        UiLanguage::German => "Update",
        UiLanguage::Spanish => "Actualizar",
        UiLanguage::Portuguese => "Atualizar",
        UiLanguage::Russian => "Обновить",
        UiLanguage::Arabic => "تحديث",
        UiLanguage::Hindi => "अपडेट",
        UiLanguage::English => "Update",
    };
    match version.filter(|value| !value.is_empty()) {
        Some(version) => format!("{base} {version}"),
        None => base.to_string(),
    }
}

