pub(crate) fn cursor_status_label(
    language: UiLanguage,
    line: usize,
    col: usize,
    selected_chars: usize,
) -> String {
    if selected_chars > 0 {
        match language {
            UiLanguage::ChineseSimplified => {
                format!("行 {line} 列 {col} (选择 {selected_chars} 字符)")
            }
            UiLanguage::ChineseTraditional => {
                format!("行 {line} 欄 {col} (選取 {selected_chars} 字元)")
            }
            _ => format!("Ln {line}, Col {col} ({selected_chars} selected)"),
        }
    } else {
        match language {
            UiLanguage::ChineseSimplified => format!("行 {line} 列 {col}"),
            UiLanguage::ChineseTraditional => format!("行 {line} 欄 {col}"),
            _ => format!("Ln {line}, Col {col}"),
        }
    }
}

