#[cfg(test)]
mod action_label_tests {
    use super::{
        UiLanguage, front_matter_type_label, open_terminal_window_label, outline_action_label,
        sidebar_visibility_action_label, terminal_settings_label, theme_action_label,
    };

    #[test]
    fn front_matter_type_labels_cover_every_language_without_duplicates() {
        let type_keys = [
            "text",
            "multiline_text",
            "checkbox",
            "date",
            "date_time",
            "list",
            "number",
            "empty",
            "object",
            "raw",
        ];
        for &language in UiLanguage::supported() {
            let mut labels = std::collections::HashSet::new();
            for key in type_keys {
                let label = front_matter_type_label(language, key);
                assert!(!label.is_empty(), "missing {language:?} {key}");
                assert!(labels.insert(label), "duplicate {language:?} {label}");
            }
            for key in ["value_type", "unsafe_conversion", "read_only", "changed"] {
                assert!(
                    !front_matter_type_label(language, key).is_empty(),
                    "missing {language:?} {key}",
                );
            }
        }
        assert_eq!(front_matter_type_label(UiLanguage::English, "text"), "Text");
        assert_eq!(
            front_matter_type_label(UiLanguage::ChineseSimplified, "unsafe_conversion"),
            "无法在不丢失数据的情况下转换此值",
        );
        assert_eq!(
            front_matter_type_label(UiLanguage::ChineseTraditional, "checkbox"),
            "核取方塊",
        );
    }

    #[test]
    fn simplified_chinese_visibility_labels_are_explicit_actions() {
        assert_eq!(
            outline_action_label(UiLanguage::ChineseSimplified, false),
            "显示大纲"
        );
        assert_eq!(
            outline_action_label(UiLanguage::ChineseSimplified, true),
            "隐藏大纲"
        );
        assert_eq!(
            sidebar_visibility_action_label(UiLanguage::ChineseSimplified, false),
            "显示边栏"
        );
        assert_eq!(
            sidebar_visibility_action_label(UiLanguage::ChineseSimplified, true),
            "隐藏边栏"
        );
    }

    #[test]
    fn terminal_settings_labels_cover_every_language() {
        let languages = [
            UiLanguage::English,
            UiLanguage::ChineseSimplified,
            UiLanguage::ChineseTraditional,
            UiLanguage::Japanese,
            UiLanguage::Korean,
            UiLanguage::French,
            UiLanguage::German,
            UiLanguage::Spanish,
            UiLanguage::Portuguese,
            UiLanguage::Russian,
            UiLanguage::Arabic,
            UiLanguage::Hindi,
        ];
        let keys = [
            "section",
            "launch_command",
            "command_args",
            "font",
            "font_size",
            "search_commands",
            "close_running_title",
            "close_running_message",
            "cursor_shape",
            "copy_on_select",
            "search_cursor_shapes",
            "block",
            "underline",
            "bar",
            "hollow",
        ];

        for language in languages {
            for key in keys {
                assert!(!terminal_settings_label(language, key).is_empty());
            }
        }
        assert_eq!(
            terminal_settings_label(UiLanguage::ChineseSimplified, "cursor_shape"),
            "光标样式"
        );
        assert_eq!(
            terminal_settings_label(UiLanguage::ChineseSimplified, "copy_on_select"),
            "选中文本以复制"
        );
    }

    #[test]
    fn open_terminal_window_labels_cover_every_language() {
        let languages = [
            UiLanguage::English,
            UiLanguage::ChineseSimplified,
            UiLanguage::ChineseTraditional,
            UiLanguage::Japanese,
            UiLanguage::Korean,
            UiLanguage::French,
            UiLanguage::German,
            UiLanguage::Spanish,
            UiLanguage::Portuguese,
            UiLanguage::Russian,
            UiLanguage::Arabic,
            UiLanguage::Hindi,
        ];

        for language in languages {
            assert!(!open_terminal_window_label(language).is_empty());
        }
        assert_eq!(
            open_terminal_window_label(UiLanguage::ChineseSimplified),
            "打开终端"
        );
    }

    #[test]
    fn simplified_chinese_theme_label_describes_the_target_appearance() {
        assert_eq!(
            theme_action_label(UiLanguage::ChineseSimplified, false),
            "切换深色"
        );
        assert_eq!(
            theme_action_label(UiLanguage::ChineseSimplified, true),
            "切换浅色"
        );
    }
}
